import{_ as e,o as a,c as s,a5 as o}from"./chunks/framework.CcrBcQWS.js";const g=JSON.parse('{"title":"Sport Client (조이스틱) — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/sport-client-joy.md","filePath":"ko/software/sdk/cpp/sport-client-joy.md","lastUpdated":1787021357000}'),d={name:"ko/software/sdk/cpp/sport-client-joy.md"};function r(i,t,n,l,h,c){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="sport-client-조이스틱-—-c-예제" tabindex="-1">Sport Client (조이스틱) — C++ 예제 <a class="header-anchor" href="#sport-client-조이스틱-—-c-예제" aria-label="Permalink to &quot;Sport Client (조이스틱) — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_sport_client_joy.cpp</code></p><p><strong>게임패드 / 조이스틱</strong>을 사용해 <code>SportClient</code> API로 로봇을 제어합니다.<br> 아날로그 스틱은 연속적인 <code>Move</code> 속도 명령을 전송하고, 버튼은 Damp, StandUp/Down, 보행 전환, 특수 동작 등의 이산 명령을 트리거합니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><p>두 개의 스레드가 동시에 실행됩니다:</p><table tabindex="0"><thead><tr><th>스레드</th><th>주기</th><th>역할</th></tr></thead><tbody><tr><td><strong>메인 스레드</strong> (조이스틱)</td><td>~100 Hz</td><td>조이스틱 이벤트 읽기, 이산 <code>SportCmd</code>를 큐에 추가, 속도 setpoint 업데이트</td></tr><tr><td><strong>제어 루프 스레드</strong></td><td>10 Hz</td><td>명령 큐를 소비하고, 비어있으면 <code>sport.Move(vx, vy, vyaw)</code> 호출</td></tr></tbody></table><p>제어 루프는 <code>sport.SetNoReply(true)</code> — fire-and-forget 방식으로 RPC 응답을 기다리지 않습니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>Linux 조이스틱 장치 (예: Logitech F710) <code>/dev/input/js*</code>.</li><li>로봇 스택이 실행 중이며 네트워크 접근 가능.</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리: <code>bin/rbq_sport_client_joy</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client_joy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [joystickPath]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 조이스틱 자동 감지:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client_joy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 장치 직접 지정:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client_joy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/input/js1</span></span></code></pre></div><p>조이스틱 경로가 없으면 Linux <code>js*</code> 장치를 자동 감지합니다 (Logitech/Xbox/Wireless 이름 우선, 이후 첫 번째 <code>js*</code> 노드 사용).<br><code>JOY</code> 환경 변수로도 경로를 지정할 수 있습니다.</p><h2 id="게임패드-버튼-매핑" tabindex="-1">게임패드 버튼 매핑 <a class="header-anchor" href="#게임패드-버튼-매핑" aria-label="Permalink to &quot;게임패드 버튼 매핑&quot;">​</a></h2><p><strong>Logitech F710 / Xbox 레이아웃</strong> (Linux 조이스틱 드라이버 기준).</p><h3 id="버튼-조합-chord-—-우선-검사" tabindex="-1">버튼 조합 (chord) — 우선 검사 <a class="header-anchor" href="#버튼-조합-chord-—-우선-검사" aria-label="Permalink to &quot;버튼 조합 (chord) — 우선 검사&quot;">​</a></h3><table tabindex="0"><thead><tr><th>누르는 버튼</th><th>로봇 동작</th></tr></thead><tbody><tr><td><strong>L2 + B</strong></td><td><code>Damp</code> — 고댐핑 비상 정지</td></tr><tr><td><strong>L2 + A</strong> <em>(첫 번째 누름)</em></td><td><code>StandUp</code> — 서기 자세로 관절 고정</td></tr><tr><td><strong>L2 + A</strong> <em>(두 번째 누름)</em></td><td><code>StandDown</code> — 엎드리기</td></tr><tr><td><strong>START</strong></td><td><code>DefaultMode</code> — 기본 보행 해제</td></tr><tr><td><strong>L2 + START</strong></td><td><code>RunningMode</code> — 고속 보행</td></tr><tr><td><strong>L2 + X</strong></td><td><code>RecoveryStand</code> — 넘어짐 후 일어서기</td></tr><tr><td><strong>R1 + X</strong></td><td><code>Climb</code> — 계단 오르기 보행</td></tr><tr><td><strong>L1 + X</strong></td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr><tr><td><strong>L1 + Y</strong></td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr><tr><td><strong>BACK</strong></td><td><code>StopMove</code> — 제자리 정지</td></tr></tbody></table><h3 id="더블-클릭-매핑" tabindex="-1">더블 클릭 매핑 <a class="header-anchor" href="#더블-클릭-매핑" aria-label="Permalink to &quot;더블 클릭 매핑&quot;">​</a></h3><p>두 번째 누름이 첫 번째 누름으로부터 <strong>400 ms</strong> 이내에 발생해야 동작합니다.</p><table tabindex="0"><thead><tr><th>버튼</th><th>동작</th></tr></thead><tbody><tr><td><strong>X</strong> 더블 클릭</td><td><code>LeftSideGait</code></td></tr><tr><td><strong>Y</strong> 더블 클릭</td><td><code>RightSideGait</code></td></tr><tr><td><strong>R1</strong> 더블 클릭</td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr><tr><td><strong>R2</strong> (트리거) 더블 클릭</td><td><strong>이 로봇에서는 지원하지 않음</strong></td></tr></tbody></table><h3 id="아날로그-스틱-속도-제어-연속" tabindex="-1">아날로그 스틱 속도 제어 (연속) <a class="header-anchor" href="#아날로그-스틱-속도-제어-연속" aria-label="Permalink to &quot;아날로그 스틱 속도 제어 (연속)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>축</th><th>매핑</th><th>최대값</th></tr></thead><tbody><tr><td>왼쪽 스틱 Y (앞으로)</td><td><code>vel_x</code> (전진)</td><td>±0.55 m/s</td></tr><tr><td>왼쪽 스틱 X (왼쪽으로)</td><td><code>vel_y</code> (횡방향)</td><td>±0.35 m/s</td></tr><tr><td>오른쪽 스틱 X</td><td><code>vyaw</code> (요 속도)</td><td>±1.0 rad/s</td></tr></tbody></table><h2 id="주요-구현-사항" tabindex="-1">주요 구현 사항 <a class="header-anchor" href="#주요-구현-사항" aria-label="Permalink to &quot;주요 구현 사항&quot;">​</a></h2><ul><li><strong><code>lock_toggle_to_prone</code></strong>: <code>L2+A</code>는 불리언 토글로 <code>StandUp</code> / <code>StandDown</code>을 번갈아 수행합니다 (A2 로봇 기본 컨트롤러 동작과 동일).</li><li><strong>더블 클릭 감지</strong>: <code>consume_double()</code> 람다가 마지막 엣지 타임스탬프를 추적하고, <code>kDoubleClickWindow(400ms)</code> 내에 두 번째 엣지가 도착하면 동작을 실행하고 카운터를 초기화합니다.</li><li><strong>R2를 가상 버튼으로 처리</strong>: RT 트리거(<code>AXIS_RT</code>)는 축 값을 0과 비교하여 버튼처럼 처리합니다 (유휴 = −1, 완전 누름 = +1).</li><li><strong>에러 누적 로깅</strong>: 연속 에러가 50번마다 한 번 출력되어 로그 스팸을 방지합니다.</li></ul><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/software/sdk/cpp/sport-client.html">Sport Client (터미널)</a></li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/high-level.html">High Level Command</a></li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a></li></ul>`,28)])])}const k=e(d,[["render",r]]);export{g as __pageData,k as default};
